function wordBreak(s, words) {
  const dict = new Set(words)
  const ok = new Array(s.length + 1).fill(false) // ok[i]: the first i characters can be split
  ok[0] = true
  for (let i = 1; i <= s.length; i++) {
    for (let j = 0; j < i; j++) {
      if (ok[j] && dict.has(s.slice(j, i))) {
        ok[i] = true
        break
      }
    }
  }
  return ok[s.length]
}

