function numDecodings(s) {
  let prev2 = 1 // ways to decode the first i - 2 characters
  let prev1 = s[0] === '0' ? 0 : 1 // ways to decode the first i - 1 characters
  for (let i = 2; i <= s.length; i++) {
    let current = 0
    if (s[i - 1] !== '0') current += prev1 // last group is one digit
    const two = Number(s.slice(i - 2, i))
    if (two >= 10 && two <= 26) current += prev2 // last group is two digits
    prev2 = prev1
    prev1 = current
  }
  return prev1
}

