def num_decodings(s):
    prev2 = 1                           # ways to decode the first i - 2 characters
    prev1 = 0 if s[0] == "0" else 1     # ways to decode the first i - 1 characters
    for i in range(2, len(s) + 1):
        current = 0
        if s[i - 1] != "0":
            current += prev1            # last group is one digit
        if 10 <= int(s[i - 2:i]) <= 26:
            current += prev2            # last group is two digits
        prev2, prev1 = prev1, current
    return prev1

