function editDistance(a, b) {
  const m = a.length
  const n = b.length
  // dist[i][j] = edits to turn the first i chars of a into the first j chars of b
  const dist = Array.from({ length: m + 1 }, (_, i) => {
    const row = new Array(n + 1).fill(0)
    row[0] = i
    return row
  })
  for (let j = 0; j <= n; j++) dist[0][j] = j
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) dist[i][j] = dist[i - 1][j - 1]
      else dist[i][j] = 1 + Math.min(dist[i - 1][j], dist[i][j - 1], dist[i - 1][j - 1]) // delete, insert, replace
    }
  }
  return dist[m][n]
}

solution.python:
def edit_distance(a, b):
    m, n = len(a), len(b)
    # dist[i][j] = edits to turn the first i chars of a into the first j chars of b
    dist = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dist[i][0] = i
    for j in range(n + 1):
        dist[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dist[i][j] = dist[i - 1][j - 1]
            else:
                dist[i][j] = 1 + min(dist[i - 1][j],      # delete a[i - 1]
                                     dist[i][j - 1],      # insert b[j - 1]
                                     dist[i - 1][j - 1])  # replace
    return dist[m][n]
